export function createDb(filename = ':memory:') {
  const db = new Database(filename);
  db.exec('CREATE TABLE products (id INTEGER PRIMARY KEY, name TEXT NOT NULL)');

  const seed = db.prepare('INSERT INTO products (id, name) VALUES (?, ?)');
  const insertMany = db.transaction(() => {
    for (let id = 1; id <= 57; id++) seed.run(id, `Product #${id}`);
  });
  insertMany();

  return db;
}
