result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "schema.js", "content": "import { buildSchema, GraphQLError } from 'graphql';

export const MAX_FIRST = 50;

export const schema = buildSchema(/* GraphQL */ `
  type Product {
    id: ID!
    name: String!
  }

  type ProductEdge {
    cursor: String!
    node: Product!
  }

  type PageInfo {
    hasNextPage: Boolean!
    endCursor: String
  }

  type ProductsConnection {
    edges: [ProductEdge!]!
    pageInfo: PageInfo!
  }

  type Query {
    products(first: Int!, after: String): ProductsConnection!
  }
`);

function encodeCursor(id) {
  return Buffer.from(String(id), 'utf8').toString('base64');
}

function decodeCursor(cursor) {
  // Strict: must be valid base64 that decodes to a positive integer id.
  if (!/^[A-Za-z0-9+/]+={0,2}$/.test(cursor)) return null;
  let decoded;
  try {
    decoded = Buffer.from(cursor, 'base64').toString('utf8');
  } catch {
    return null;
  }
  const id = Number(decoded);
  if (!Number.isInteger(id) || id < 1) return null;
  return id;
}

export function rootValue(db) {
  return {
    products({ first, after }) {
      if (!Number.isInteger(first) || first < 1) {
        throw new GraphQLError('`first` must be a positive integer', {
          extensions: { code: 'BAD_USER_INPUT' },
        });
      }
      first = Math.min(first, MAX_FIRST);

      let afterId = 0;
      if (after !== undefined && after !== null) {
        afterId = decodeCursor(after);
        if (afterId === null || !db.prepare('SELECT 1 FROM products WHERE id = ?').get(afterId)) {
          throw new GraphQLError(`Invalid cursor: ${JSON.stringify(after)}`, {
            extensions: { code: 'INVALID_CURSOR' },
          });
        }
      }

      const rows = db
        .prepare('SELECT id, name FROM products WHERE id > ? ORDER BY id LIMIT ?')
        .all(afterId, first + 1);

      const hasNextPage = rows.length > first;
      const page = hasNextPage ? rows.slice(0, first) : rows;
      const last = page.at(-1);

      return {
        edges: page.map((row) => ({ cursor: encodeCursor(row.id), node: row })),
        pageInfo: {
          hasNextPage,
          endCursor: last ? encodeCursor(last.id) : null,
        },
      };
    },
  };
}
"})
