result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "server.js", "content": "import express from 'express';
import { createHandler } from 'graphql-http/lib/use/express';
import { createDb } from './db.js';
import { schema, rootValue } from './schema.js';

export function createApp({ db = createDb() } = {}) {
  const app = express();
  app.all(
    '/graphql',
    createHandler({
      schema,
      rootValue: rootValue(db),
    })
  );
  return app;
}

// istanbul ignore next
if (process.argv[1] === new URL(import.meta.url).pathname) {
  const app = createApp();
  const port = Number(process.env.PORT || 4000);
  app.listen(port, () => {
    console.log(`GraphQL server listening on http://localhost:${port}/graphql`);
  });
}
"})
