result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "test/pagination.test.js", "content": "import test from 'node:test';
import assert from 'node:assert/strict';

import { createApp } from '../server.js';
import { createDb } from '../db.js';
import { MAX_FIRST } from '../schema.js';

const encode = (id) => Buffer.from(String(id), 'utf8').toString('base64');

async function gql(app, query, variables) {
  const server = app.listen(0);
  try {
    const res = await fetch(`http://127.0.0.1:${server.address().port}/graphql`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ query, variables }),
    });
    return await res.json();
  } finally {
    server.close();
  }
}

const PAGE_QUERY = `
  query ($first: Int!, $after: String) {
    products(first: $first, after: $after) {
      edges { cursor node { id name } }
      pageInfo { hasNextPage endCursor }
    }
  }
`;

test('walking pages of 10 covers exactly 57 unique products and hasNextPage flips on the last page', async () => {
  const app = createApp({ db: createDb() });

  const ids = [];
  const names = [];
  let after = undefined;
  let pages = 0;

  for (;;) {
    const { data, errors } = await gql(app, PAGE_QUERY, { first: 10, after });
    assert.ifError(errors);

    const connection = data.products;
    pages++;

    if (pages < 6) {
      // Pages 1-5 are full: hasNextPage true, cursor present.
      assert.equal(connection.edges.length, 10, `page ${pages} should have 10 edges`);
      assert.equal(connection.pageInfo.hasNextPage, true, `page ${pages} should have a next page`);
    } else {
      assert.equal(pages, 6, 'should not need more than 6 pages');
      assert.equal(connection.edges.length, 7, 'last page has the remaining 7 edges');
      assert.equal(connection.pageInfo.hasNextPage, false, 'hasNextPage flips false on the last page');
    }

    for (const edge of connection.edges) {
      assert.equal(edge.cursor, encode(edge.node.id), 'cursor is base64 of the id');
      ids.push(Number(edge.node.id));
      names.push(edge.node.name);
    }

    if (!connection.pageInfo.hasNextPage) {
      assert.equal(connection.pageInfo.endCursor, encode(57), 'endCursor of last page is id 57');
      break;
    }
    after = connection.pageInfo.endCursor;
  }

  assert.equal(pages, 6);
  assert.equal(ids.length, 57);
  assert.deepEqual([...ids].sort((a, b) => a - b), Array.from({ length: 57 }, (_, i) => i + 1));
  assert.equal(new Set(ids).size, 57, 'all nodes unique');
  assert.equal(names[0], 'Product #1');
  assert.equal(names.at(-1), 'Product #57');

  // No overlap between consecutive pages.
  const seen = new Set();
  for (const id of ids) {
    assert.ok(!seen.has(id), `node ${id} appeared twice`);
    seen.add(id);
  }
});

test('an invalid cursor yields a GraphQL error with extensions.code INVALID_CURSOR', async () => {
  const app = createApp({ db: createDb() });

  for (const after of [encode('9999'), encode('not-a-number'), '!!!not-base64!!!']) {
    const { data, errors } = await gql(app, PAGE_QUERY, { first: 10, after });
    assert.equal(data, undefined, 'no data for invalid cursor');
    assert.equal(errors?.length, 1, 'exactly one GraphQL error');
    assert.match(errors[0].message, /Invalid cursor/);
    assert.equal(errors[0].extensions?.code, 'INVALID_CURSOR');
  }
});

test('first > 50 is capped at 50', async () => {
  const app = createApp({ db: createDb() });

  const { data, errors } = await gql(app, PAGE_QUERY, { first: 100 });
  assert.ifError(errors);

  const connection = data.products;
  assert.equal(connection.edges.length, MAX_FIRST, 'edges capped at 50');
  assert.equal(connection.edges[0].node.id, '1');
  assert.equal(connection.edges.at(-1).node.id, String(MAX_FIRST));
  assert.equal(connection.pageInfo.hasNextPage, true, 'there is more beyond the cap');
  assert.equal(connection.pageInfo.endCursor, encode(MAX_FIRST));

  // And the capped page still chains correctly.
  const next = await gql(app, PAGE_QUERY, {
    first: 10,
    after: connection.pageInfo.endCursor,
  });
  assert.ifError(next.errors);
  assert.equal(next.data.products.edges[0].node.id, String(MAX_FIRST + 1));
});
"})
